import { watchDom } from '../../core/observer';
import { create, wasApplied, markApplied } from '../../utils/dom';
import { createIcon } from '../../utils/icons';

const LOGO_URL = '/assets/logo/banner-light.png';

function applyHeaderLogo() {
    const header = document.querySelector('.skinHeader');
    if (!header) return;

    header.classList.add('ptv-header');
}

function applyHeaderIcons() {
    const buttons = document.querySelectorAll(
        '.skinHeader button, .skinHeader .headerButton, .skinHeader a'
    );

    buttons.forEach((button) => {
        if (wasApplied(button, 'ptvHeaderIcon')) return;

        const label = button.getAttribute('title')
            || button.getAttribute('aria-label')
            || button.textContent
            || '';

        const key = label.toLowerCase();

        let icon = '';

        if (key.includes('home')) icon = 'home';
        if (key.includes('search')) icon = 'search';
        if (key.includes('settings')) icon = 'settings';
        if (key.includes('dashboard')) icon = 'dashboard';
        if (key.includes('profile') || key.includes('user')) icon = 'profile';
        if (key.includes('server')) icon = 'server';

        if (!icon) return;

        markApplied(button, 'ptvHeaderIcon');
        button.classList.add('ptv-header-icon-button');

        const oldIcon = button.querySelector(
            '.material-icons, .material-icons-round, .material-icons-outlined, i'
        );

        if (oldIcon) {
            oldIcon.classList.add('ptv-hidden-stock-icon');
        }

        if (!button.querySelector('.ptv-icon')) {
            button.prepend(createIcon(icon, 'ptv-icon ptv-header-icon'));
        }
    });
}

function runHeader() {
    applyHeaderLogo();
    applyHeaderIcons();
}

watchDom(runHeader);
runHeader();
